# Pruebas de la migración 003 con solicitudes directas a la API
import json, secrets, psycopg
exec(open('prueba_rls.py').read().split("print('\\n— Taller sin cuenta —')")[0])
c=psycopg.connect('host=127.0.0.1 port=54322 user=postgres dbname=postgres',autocommit=True)
q=lambda s,*a: c.execute(s,a if a else None).fetchall()
D1='disp_'+secrets.token_hex(12); D2='disp_'+secrets.token_hex(12); D3='disp_'+secrets.token_hex(12)
rpc('ast_registrar_dispositivo',{'p_id':D1,'p_nombre':'Pedro Rojas','p_rut':'','p_cargo':'','p_agente':'x'})
adm=login('lcortes','Prueba22026'); sup=login('bmendoza','Prueba32026')
rpc('ast_registrar_dispositivo',{'p_id':D2,'p_nombre':'','p_rut':'','p_cargo':'','p_agente':'x'},adm)
rpc('ast_registrar_dispositivo',{'p_id':D3,'p_nombre':'','p_rut':'','p_cargo':'','p_agente':'x'},sup)
antes=q('select count(*) from ast_registros')[0][0]

print('\n— Perfiles nuevos —')
