ok('Se crea una cuenta de Planificador', s==200)
s,d=rpc('ast_admin_crear_usuario',{'p_usuario':'visita1','p_nombre':'Vico','p_apellido':'Visita','p_rut':'','p_cargo':'Auditor','p_rol':'visitante','p_clave':'Visita2026','p_orden':100},adm,D2)
ok('Se crea una cuenta de Visitante', s==200)
s,d=rpc('ast_admin_crear_usuario',{'p_usuario':'debil1','p_nombre':'D','p_apellido':'D','p_rut':'','p_cargo':'','p_rol':'visitante','p_clave':'solotexto','p_orden':100},adm,D2)
ok('Rechaza una clave temporal sin números', s>=400)
pl=login('plan1','Planif2026'); vi=login('visita1','Visita2026')
rpc('ast_registrar_dispositivo',{'p_id':'disp_'+secrets.token_hex(12),'p_nombre':'','p_rut':'','p_cargo':'','p_agente':'x'},pl)
Dp='disp_'+secrets.token_hex(12); rpc('ast_registrar_dispositivo',{'p_id':Dp,'p_nombre':'','p_rut':'','p_cargo':'','p_agente':'x'},pl)
Dv='disp_'+secrets.token_hex(12); rpc('ast_registrar_dispositivo',{'p_id':Dv,'p_nombre':'','p_rut':'','p_cargo':'','p_agente':'x'},vi)
s,p=rpc('ast_mi_perfil',{},pl,Dp); ok('Planificador: ve histórico y dashboard, no firma (%s)'%p['niveles'], p['rolNombre']=='Planificador' and p['niveles']['historico']==1 and p['niveles']['firmas']==1 and p['niveles']['papelera']==0)
s,d=req('GET','/rest/v1/ast_registros?select=id',tok=pl,disp=Dp); ok('Planificador lee las AST', s==200 and len(d)>=6)
s,d=req('PATCH','/rest/v1/ast_registros?id=eq.hoy1',{'sup_firma':'data:x','estado':'firmada'},pl,Dp); ok('Planificador no puede firmar', s>=400 or d==[])
s,d=req('POST','/rest/v1/ast_registros',{'id':'pl1','fecha':hoy,'area':'ensamble','linea':'L8','estado':'borrador'},pl,Dp); ok('Planificador no crea AST', s>=400)
s,p=rpc('ast_mi_perfil',{},vi,Dv); ok('Visitante: solo lectura', p['rolNombre']=='Visitante' and p['niveles']['ast_dia']==1 and p['niveles']['firmas']==0)
s,d=req('POST','/rest/v1/ast_registros',{'id':'vi1','fecha':hoy,'area':'ensamble','linea':'L8','estado':'borrador'},vi,Dv); ok('Visitante no crea AST', s>=400)
s,d=rpc('ast_firmantes',{},adm,D2); ok('Planificador y Visitante no aparecen en «Se envía a firma de»', not any(x['nombre'] in ('Pía Plan','Vico Visita') for x in d))

print('\n— Claves temporales —')
r=q("select clave_temporal_en is not null, clave_temporal_vence - clave_temporal_en from ast_perfiles where usuario='plan1'")[0]
ok('La cuenta nueva guarda fecha de creación y vencimiento a 7 días', r[0] and r[1].days==7)
s,d=req('GET','/rest/v1/ast_perfiles?select=usuario,cambiar_clave,clave_temporal_vence&usuario=eq.plan1',tok=adm,disp=D2)
ok('El administrador ve quién tiene clave temporal y cuándo vence', d and d[0]['cambiar_clave'] and d[0]['clave_temporal_vence'])
ok('La tabla de cuentas no guarda ninguna contraseña', not q("select 1 from information_schema.columns where table_name='ast_perfiles' and column_name ilike '%clave%' and column_name not in ('cambiar_clave','clave_temporal_en','clave_temporal_vence')"))
c.execute("update ast_perfiles set clave_temporal_en=now()-interval '9 days', clave_temporal_vence=now()-interval '2 days' where usuario='visita1'")
s,p=rpc('ast_mi_perfil',{},vi,Dv); ok('Clave temporal vencida: la app lo sabe', p['claveVencida'] is True)
ok('…y la cuenta queda sin acceso a nada', all(v==0 for v in p['niveles'].values()))
s,d=req('GET','/rest/v1/ast_registros?select=id',tok=vi,disp=Dv); ok('…ni siquiera puede leer AST', d==[])
s,d=rpc('ast_cambie_mi_clave',{},vi,Dv); ok('…ni dar por cambiada su clave', s>=400)
uid=q("select id from ast_perfiles where usuario='visita1'")[0][0]
s,d=rpc('ast_admin_clave',{'p_id':str(uid),'p_clave':'Nueva2026x'},adm,D2); ok('El administrador genera otra clave temporal', s in (200,204))
r=q("select clave_temporal_vence > now() + interval '6 days' from ast_perfiles where usuario='visita1'")[0][0]
ok('La clave nueva vuelve a durar 7 días', r)
s,d=rpc('ast_admin_clave',{'p_id':str(uid),'p_clave':'cortita'},adm,D2); ok('Rechaza una clave débil', s>=400)
vi=login('visita1','Nueva2026x'); s,d=rpc('ast_cambie_mi_clave',{},vi,Dv); ok('Con la clave nueva puede cambiarla', s in (200,204))
ok('Al cambiarla, desaparece la marca de clave temporal', q("select cambiar_clave, clave_temporal_vence from ast_perfiles where usuario='visita1'")[0]==(False,None))
s,d=rpc('ast_admin_clave',{'p_id':str(uid),'p_clave':'Otra2026xx'},sup,D3); ok('Un supervisor no puede generar claves', s>=400)

print('\n— Papelera —')
s,d=req('PATCH','/rest/v1/ast_registros?id=eq.hoy1',{'sup_firma':'data:img','estado':'firmada','contenido':{'descripcion':'hoy'}},sup,D3)
num=d[0]['contenido']['correlativo']; firma0=d[0]['sup_firma']; ok('AST de hoy firmada con número %s'%num, s==200)
req('POST','/rest/v1/ast_participantes',{'id':'pz1','ast_id':'hoy1','nombre':'Rosa Díaz','rut':'11.111.111-1','firma':'data:f'},disp=D1)
s,d=rpc('ast_eliminar',{'p_id':'hoy1','p_motivo':'prueba'},sup,D3); ok('Un supervisor no puede eliminar AST', s>=400)
s,d=rpc('ast_eliminar',{'p_id':'hoy1','p_motivo':'x'},adm,D2); ok('Sin motivo no se puede eliminar', s>=400)
s,d=rpc('ast_eliminar',{'p_id':'hoy1','p_motivo':'Creada por error en la línea equivocada'},adm,D2); ok('El administrador la envía a la papelera', s==200 and d['ok'])
s,d=rpc('ast_eliminar',{'p_id':'hoy1','p_motivo':'otra vez'},adm,D2); ok('No se puede eliminar dos veces', s>=400)
for nom,t,dd in [('el taller',None,D1),('el supervisor',sup,D3),('el administrador',adm,D2)]:
    s,d=req('GET','/rest/v1/ast_registros?select=id&id=eq.hoy1',tok=t,disp=dd); ok('Ya no aparece en las listas para '+nom, d==[])
s,d=req('GET','/rest/v1/ast_participantes?select=id&ast_id=eq.hoy1',tok=sup,disp=D3); ok('Sus participantes tampoco aparecen', d==[])
s,d=req('PATCH','/rest/v1/ast_registros?id=eq.hoy1',{'sup_obs':'x'},adm,D2); ok('Nadie la puede modificar en la papelera', s>=400 or d==[])
s,d=req('POST','/rest/v1/ast_participantes',{'id':'pz2','ast_id':'hoy1','nombre':'Otro','rut':'','firma':'data:f'},disp=D1); ok('No se agregan participantes a una AST en la papelera', s>=400)
ok('No se borró nada: la AST, su firma y su número siguen en la base', q("select count(*) from ast_registros")[0][0]==antes and
   q("select sup_firma from ast_registros where id='hoy1'")[0][0]==firma0 and q("select numero from ast_correlativos where ast_id='hoy1'")[0][0]==num)
s,d=rpc('ast_papelera_lista',{},sup,D3); ok('Un supervisor no ve la papelera', s>=400)
s,d=rpc('ast_papelera_lista',{},adm,D2); x=[z for z in d if z['id']=='hoy1']
ok('El administrador la ve en la papelera con número, motivo y quién la eliminó', x and x[0]['numero']==num and 'error' in x[0]['motivo'] and x[0]['eliminada_por']=='Luis Cortés')
s,d=req('GET','/rest/v1/ast_papelera?select=*',tok=adm,disp=D2); ok('La tabla de la papelera no se puede leer ni tocar directo', s>=400 or d==[])
s,d=rpc('ast_recuperar',{'p_id':'hoy1'},sup,D3); ok('Un supervisor no puede recuperar', s>=400)
s,d=rpc('ast_recuperar',{'p_id':'hoy1'},adm,D2); ok('El administrador la recupera', s==200 and d['ok'])
s,d=req('GET','/rest/v1/ast_registros?select=id,sup_firma,contenido&id=eq.hoy1',tok=sup,disp=D3)
ok('Vuelve a las listas con el mismo número y la misma firma', d and d[0]['contenido']['correlativo']==num and d[0]['sup_firma']==firma0)
s,d=req('GET','/rest/v1/ast_participantes?select=id&ast_id=eq.hoy1',tok=sup,disp=D3); ok('…y con sus participantes', len(d)>=1)
s,d=req('GET','/rest/v1/ast_accesos?select=accion,detalle&order=id.desc&limit=60',tok=adm,disp=D2); acc=[z['accion'] for z in d]
ok('El historial registra la eliminación (con motivo) y la recuperación', 'Recuperó una AST de la papelera' in acc and
   any(z['accion'].startswith('Eliminó una AST') and 'motivo: Creada por error' in z['detalle'] for z in d))
ok('Queda el historial interno de la papelera', q("select string_agg(accion,',' order by id) from ast_papelera_historial where ast_id='hoy1'")[0][0]=='eliminada,recuperada')

print('\n— Motivo de incorporación —')
s,d=req('POST','/rest/v1/ast_participantes',{'id':'pm1','ast_id':'hoy1','nombre':'Tomás Tarde','rut':'22.222.222-2','firma':'data:f','motivo':'Llegó después de la charla'},disp=D1)
ok('Participante después de la firma guarda su motivo', s==201 and d[0]['post_firma'] and d[0]['motivo']=='Llegó después de la charla')
s,d=req('POST','/rest/v1/ast_participantes',{'id':'pm2','ast_id':'hoy1','nombre':'Sin Motivo','rut':'','firma':'data:f'},disp=D1)
ok('Si una versión antigua no manda motivo, queda «Sin motivo indicado»', s==201 and d[0]['motivo']=='Sin motivo indicado')
s,d=req('GET','/rest/v1/ast_accesos?select=accion,detalle&order=id.desc&limit=10',tok=adm,disp=D2)
ok('El historial muestra el motivo', any('motivo: Llegó después' in z['detalle'] for z in d))
s,d=req('GET','/rest/v1/ast_registros?select=sup_firma,contenido&id=eq.hoy1',tok=sup,disp=D3)
ok('Las firmas y el número no cambiaron', d[0]['sup_firma']==firma0 and d[0]['contenido']['correlativo']==num)

print('\n— Se puede volver a correr —')
c.execute(open('sql/04_papelera_roles_claves.sql').read())
ok('La migración 003 corre otra vez sin error ni cambios', q('select count(*) from ast_registros')[0][0]==antes and q("select count(*) from ast_participantes where ast_id='hoy1'")[0][0]>=3)
